    method: 'Method', userAgent: 'User-Agent', responseStatus: 'Status', responseSize: 'Response size', allStatuses: 'All statuses', statusSuccess: 'Success', statusRedirect: 'Redirect', statusClientError: 'Client error', statusServerError: 'Server error', onlyRequestsWithoutBurst: 'Only requests without a burst',
